# Generated by build.py from recipe.yml for recipe smb-read-a-share. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/docs', 'site/docs/notes' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/docs/readme.txt'), "read me first`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/docs/notes/todo.txt'), "water the plants`n")
[IO.File]::WriteAllText((Join-Path $PWD 'report.txt'), "quarterly numbers`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--auth', 'ntlmv1', '-u', 'alice:s3cret', 'smb://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -u alice:s3cret smb://127.0.0.1:8080/docs/readme.txt } finally { Stop-Process $server0 }
